steps.action:
curl -s https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: Bearer <TOKEN>" \
  -d '{
    "query": {
      "issue": {
        "orderBy": { "field": "number", "direction": "ASC" },
        "filter": { "number": { "eq": 42 }, "team": { "key": { "eq": "MOB" } } },
        "first": 1,
        "fields": ["id", "identifier", "title", "subIssues { first: 20 fields [id identifier title estimate dueDate priority] }"]
      }
    }
  }'

curl -s https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: Bearer <TOKEN>" \
  -d '{
    "query": "query { issue(filter: { number: { eq: 42 }, team: { key: { eq: \"MOB\" } } }) { id identifier title subIssues(first: 20) { nodes { id identifier title estimate dueDate priority } } } }"
  }'

curl -s https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: Bearer <TOKEN>" \
  -d '{
    "query": "query { issues(first: 5, orderBy: { field: \"number\", direction: \"DESC\" }) { nodes { id identifier title } } }"
  }'

curl -s https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: Bearer <TOKEN>" \
  -d '{
    "query": "query { issues(first: 5, filter: { identifier: { eq: \"MOB-42\" } }) { nodes { id identifier title estimate dueDate priority parent { id identifier title } } } }"
  }'

curl -s https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: Bearer <TOKEN>" \
  -d '{
    "query": "query { teams { nodes { id name key } } }"
  }'

curl -s https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: Bearer <TOKEN>" \
  -d '{
    "query": "query { issues(first: 5, filter: { team: { key: { eq: \"MOB\" } }, number: { eq: 42 } }) { nodes { id identifier title estimate dueDate priority } } }"
  }'

curl -s https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: Bearer <TOKEN>" \
  -d '{
    "query": "query { issues(first: 20, filter: { parent: { id: { eq: \"i-mob-42\" } } }) { nodes { id identifier title estimate dueDate priority } } }"
  }'
